args.query:
SELECT team_id_home, team_abbreviation_home, team_id_away, team_abbreviation_away 
FROM other_stats 
WHERE game_id = '0021500003';

SELECT team_id_home, team_abbreviation_home, team_id_away, team_abbreviation_away 
FROM game 
WHERE game_id = '0021500003';

SELECT COUNT(*) 
FROM game g 
JOIN other_stats o ON g.game_id = o.game_id;

SELECT COUNT(DISTINCT game_id) 
FROM play_by_play 
WHERE game_id NOT IN (SELECT game_id FROM other_stats);
